  `hip_circumference_cm` decimal(5,2) DEFAULT NULL,
  `waist_hip_ratio` decimal(4,3) DEFAULT NULL,
  `weight_management` varchar(50) DEFAULT NULL,
  `food_recommendation` varchar(100) DEFAULT NULL,
  `measured_by` int(11) DEFAULT NULL,
  `staff_signature` varchar(255) DEFAULT NULL,
  `measurement_date` date DEFAULT NULL,
  `notes` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `mac_cm` decimal(5,2) DEFAULT NULL,
  `cc_cm` decimal(5,2) DEFAULT NULL,
