  UNIQUE KEY `uq_bia_visit` (`visit_id`),
  KEY `measured_by` (`measured_by`),
  KEY `ix_bia_records_id` (`id`),
  KEY `ix_bia_records_created_at` (`created_at`),
  KEY `ix_bia_records_visit_id` (`visit_id`),
  CONSTRAINT `bia_records_ibfk_1` FOREIGN KEY (`visit_id`) REFERENCES `visits` (`id`) ON DELETE CASCADE,
  CONSTRAINT `bia_records_ibfk_2` FOREIGN KEY (`measured_by`) REFERENCES `users` (`id`)
