--
-- Table structure for table `respondents`
--

DROP TABLE IF EXISTS `respondents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `respondents` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `respondent_code` varchar(50) NOT NULL,
  `status` enum('ELDERLY','CAREGIVER') DEFAULT NULL,
  `age` int(11) DEFAULT NULL,
  `sex` enum('MALE','FEMALE','OTHER','PREFER_NOT_TO_SAY') DEFAULT NULL,
  `education_level` varchar(50) DEFAULT NULL,
  `marital_status` varchar(50) DEFAULT NULL,
  `monthly_income` varchar(50) DEFAULT NULL,
  `income_sources` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `chronic_diseases` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `living_arrangement` varchar(50) DEFAULT NULL,
  `income_range` varchar(50) DEFAULT NULL,
  `occupation` varchar(100) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) DEFAULT NULL,
