DROP TABLE IF EXISTS `sansa_prediction_results`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sansa_prediction_results` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `visit_id` int(11) NOT NULL,
  `model_version` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `age_group01` int(11) NOT NULL,
  `d2_total` decimal(12,4) NOT NULL,
  `d3_total` decimal(12,4) NOT NULL,
  `waist_cm` decimal(12,4) NOT NULL,
  `l_over` decimal(24,12) NOT NULL,
  `l_normal` decimal(24,12) NOT NULL,
  `p_under` decimal(18,16) NOT NULL,
  `p_normal` decimal(18,16) NOT NULL,
  `p_over` decimal(18,16) NOT NULL,
  `predicted_group` enum('UNDER','NORMAL','OVER') COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sansa_prediction_visit_version` (`visit_id`,`model_version`),
  CONSTRAINT `sansa_prediction_results_ibfk_1` FOREIGN KEY (`visit_id`) REFERENCES `visits` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=203 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

