--
-- Table structure for table `sansa_responses`
--

DROP TABLE IF EXISTS `sansa_responses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sansa_responses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `visit_id` int(11) NOT NULL,
  `scoring_version_id` int(11) NOT NULL,
  `q1_weight_change` varchar(50) DEFAULT NULL,
  `q1_score` decimal(10,2) DEFAULT NULL,
  `q2_food_intake` varchar(50) DEFAULT NULL,
  `q2_score` decimal(10,2) DEFAULT NULL,
  `q3_daily_activities` varchar(50) DEFAULT NULL,
  `q3_score` decimal(10,2) DEFAULT NULL,
  `q4_chronic_disease` varchar(50) DEFAULT NULL,
  `q4_score` decimal(10,2) DEFAULT NULL,
  `q5_meals_per_day` varchar(50) DEFAULT NULL,
  `q5_score` decimal(10,2) DEFAULT NULL,
  `q6_portion_size` varchar(50) DEFAULT NULL,
  `q6_score` decimal(10,2) DEFAULT NULL,
  `q7_food_texture` varchar(50) DEFAULT NULL,
  `q7_score` decimal(10,2) DEFAULT NULL,
  `q8_rice_starch` varchar(50) DEFAULT NULL,
  `q8_score` decimal(10,2) DEFAULT NULL,
  `q9_protein` varchar(50) DEFAULT NULL,
  `q9_score` decimal(10,2) DEFAULT NULL,
  `q10_milk` varchar(50) DEFAULT NULL,
  `q10_score` decimal(10,2) DEFAULT NULL,
  `q11_fruits` varchar(50) DEFAULT NULL,
  `q11_score` decimal(10,2) DEFAULT NULL,
  `q12_vegetables` varchar(50) DEFAULT NULL,
  `q12_score` decimal(10,2) DEFAULT NULL,
  `q13_water` varchar(50) DEFAULT NULL,
  `q13_score` decimal(10,2) DEFAULT NULL,
  `q14_sweet_drinks` varchar(50) DEFAULT NULL,
  `q14_score` decimal(10,2) DEFAULT NULL,
  `q15_cooking_method` varchar(50) DEFAULT NULL,
  `q15_score` decimal(10,2) DEFAULT NULL,
  `q16_oil_coconut` varchar(50) DEFAULT NULL,
  `q16_score` decimal(10,2) DEFAULT NULL,
  `screening_total` decimal(10,2) DEFAULT NULL,
  `screening_status` tinyint(1) DEFAULT NULL COMMENT 'scr_status: 0=ปกติ, 1=เสี่ยงทุพโภชนาการ',
  `diet_total` decimal(10,2) DEFAULT NULL,
  `assessment_result` tinyint(1) DEFAULT NULL COMMENT 'ass_result: 0=ปกติ, 1=เสี่ยง, 2=ขาด, 3=เกิน',
  `total_score` decimal(10,2) DEFAULT NULL,
  `result_level` varchar(50) DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `source_dataset` varchar(100) DEFAULT NULL,
  `answer_capture_mode` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`id`),
