DROP TABLE IF EXISTS `satisfaction_responses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `satisfaction_responses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `visit_id` int(11) NOT NULL,
  `q1_clarity` int(11) DEFAULT NULL,
  `q2_ease_of_use` int(11) DEFAULT NULL,
  `q3_confidence` int(11) DEFAULT NULL,
  `q4_presentation` int(11) DEFAULT NULL,
  `q5_results_display` int(11) DEFAULT NULL,
  `q6_usefulness` int(11) DEFAULT NULL,
  `q7_overall_satisfaction` int(11) DEFAULT NULL,
  `comments` text,
  `total_score` decimal(5,2) DEFAULT NULL COMMENT 'sat_total: ผลรวม q1-q7',
  `mean_score` decimal(4,2) DEFAULT NULL COMMENT 'sat_mean: ผลรวม/7',
  `satisfaction_level` tinyint(1) DEFAULT NULL COMMENT 'sat_level: 1=น้อย(1.00-2.33), 2=กลาง(2.34-3.66), 3=สูง(3.67-5.00)',
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_satisfaction_responses_visit_id` (`visit_id`),
  KEY `ix_satisfaction_responses_id` (`id`),
  CONSTRAINT `satisfaction_responses_ibfk_1` FOREIGN KEY (`visit_id`) REFERENCES `visits` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=408 DEFAULT CHARSET=utf8;
